import{_ as t,o as n,c as d,a2 as o}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"MCP-Tools","description":"","frontmatter":{},"headers":[],"relativePath":"de/mcp-tools/overview.md","filePath":"de/mcp-tools/overview.md","lastUpdated":1784903584000}'),r={name:"de/mcp-tools/overview.md"};function i(a,e,s,c,l,h){return n(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="mcp-tools" tabindex="-1">MCP-Tools <a class="header-anchor" href="#mcp-tools" aria-label="Permalink to &quot;MCP-Tools&quot;">​</a></h1><h2 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h2><p>swag2mcp bietet <strong>19 MCP-Tools</strong>, die einem LLM-Agenten über das Model Context Protocol vollen Zugriff auf Ihre APIs geben. Diese Tools decken den gesamten Arbeitsablauf ab: Entdecken, welche APIs verfügbar sind, Navigieren in der Spec-Hierarchie, Suchen und Inspizieren von Endpunkten, Ausführen von API-Aufrufen und Arbeiten mit großen Antworten.</p><h3 id="was-die-tools-losen" tabindex="-1">Was die Tools lösen <a class="header-anchor" href="#was-die-tools-losen" aria-label="Permalink to &quot;Was die Tools lösen&quot;">​</a></h3><ul><li><strong>Erkennung</strong> — der LLM kann Specs, Collections und Tags finden, ohne IDs im Voraus zu kennen</li><li><strong>Navigation</strong> — von Spec → Collection → Tag → Endpunkt in einer strukturierten Hierarchie hineinzoomen</li><li><strong>Suche</strong> — Volltextsuche über alle Endpunkte, wenn Sie keine ID haben</li><li><strong>Inspektion</strong> — das vollständige OpenAPI-Operationsobjekt vor einem Aufruf abrufen</li><li><strong>Ausführung</strong> — echte API-Aufrufe mit automatischer Authentifizierung durchführen</li><li><strong>Große Antworten verarbeiten</strong> — übergroße Antworten, die nicht inline passen, gliedern, komprimieren und aufteilen</li></ul><h3 id="schreibgeschutzt-vs-veranderlich" tabindex="-1">Schreibgeschützt vs. Veränderlich <a class="header-anchor" href="#schreibgeschutzt-vs-veranderlich" aria-label="Permalink to &quot;Schreibgeschützt vs. Veränderlich&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Typ</th><th>Anzahl</th><th>Tools</th></tr></thead><tbody><tr><td><strong>Schreibgeschützt</strong></td><td>17</td><td>Alle Erkennungs-, Endpunkt-, Such-, Inspektions-, Info- und Antwort-Tools</td></tr><tr><td><strong>Veränderlich</strong></td><td>2</td><td><code>invoke</code> (führt echte HTTP-Aufrufe durch), <code>auth</code> (ruft Tokens ab)</td></tr></tbody></table><p>Schreibgeschützte Tools sind mit <code>ReadOnlyHint=true</code> und <code>IdempotentHint=true</code> im MCP-Protokoll markiert, was dem LLM signalisiert, dass sie ohne Nebenwirkungen sicher aufgerufen werden können.</p><h3 id="fehlerbehandlung" tabindex="-1">Fehlerbehandlung <a class="header-anchor" href="#fehlerbehandlung" aria-label="Permalink to &quot;Fehlerbehandlung&quot;">​</a></h3><p>Alle Tools geben Fehler als strukturierte <code>LLMError</code>-Objekte mit einem maschinenlesbaren Code und einer menschenlesbaren Nachricht zurück, die erklärt, was schiefgelaufen ist und was als nächstes zu tun ist:</p><table tabindex="0"><thead><tr><th>Fehlercode</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>validation_failed</code></td><td>Ungültige Eingabe (falsches ID-Format, fehlende Pflichtfelder)</td></tr><tr><td><code>not_found</code></td><td>Entität nicht im Index oder Arbeitsbereich gefunden</td></tr><tr><td><code>rate_limit</code></td><td>Zweiter <code>invoke</code>-Aufruf innerhalb von 10 Sekunden auf demselben Endpunkt</td></tr><tr><td><code>invoke_error</code></td><td>HTTP-Aufruffehler, Download-Fehler</td></tr><tr><td><code>auth_error</code></td><td>Fehler beim Abrufen des Auth-Tokens</td></tr><tr><td><code>config_error</code></td><td>Fehler beim Laden oder Speichern der Konfigurationsdatei</td></tr><tr><td><code>parse_error</code></td><td>Fehler beim Parsen der Spezifikationsdatei</td></tr></tbody></table><h2 id="kategorien" tabindex="-1">Kategorien <a class="header-anchor" href="#kategorien" aria-label="Permalink to &quot;Kategorien&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kategorie</th><th>Tools</th><th>Beschreibung</th></tr></thead><tbody><tr><td><strong>Erkennung</strong></td><td><code>spec_list</code>, <code>spec_by_id</code>, <code>collection_by_spec</code>, <code>collection_by_id</code>, <code>tag_by_spec</code>, <code>tag_by_collection</code>, <code>tag_by_id</code></td><td>In der Spec-Hierarchie navigieren: Specs, Collections und Tags finden</td></tr><tr><td><strong>Endpunkte</strong></td><td><code>endpoint_by_spec</code>, <code>endpoint_by_collection</code>, <code>endpoint_by_tag</code>, <code>endpoint_by_id</code></td><td>Endpunkte auf verschiedenen Ebenen der Hierarchie anzeigen</td></tr><tr><td><strong>Ausführung</strong></td><td><code>search</code>, <code>inspect</code>, <code>invoke</code></td><td>Suchen, den vollständigen Vertrag inspizieren und APIs aufrufen</td></tr><tr><td><strong>Hilfsprogramme</strong></td><td><code>auth</code>, <code>info</code>, <code>response_outline</code>, <code>response_compress</code>, <code>response_slice</code></td><td>Auth-Tokens, Laufzeitinfo und Verarbeitung großer Antworten</td></tr><tr><td><strong>Skills</strong></td><td><a href="/mcp-tools/skills">Formatierungsleitfaden</a></td><td>Anpassen, wie Tool-Antworten angezeigt werden</td></tr></tbody></table><h2 id="vollstandige-liste" tabindex="-1">Vollständige Liste <a class="header-anchor" href="#vollstandige-liste" aria-label="Permalink to &quot;Vollständige Liste&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Beschreibung</th></tr></thead><tbody><tr><td><code>spec_list</code></td><td>Alle API-Spezifikationen im Arbeitsbereich auflisten</td></tr><tr><td><code>spec_by_id</code></td><td>Detaillierte Spec-Informationen mit Collections abrufen</td></tr><tr><td><code>collection_by_spec</code></td><td>Collections innerhalb einer Spec auflisten</td></tr><tr><td><code>collection_by_id</code></td><td>Collection-Details mit Tags abrufen</td></tr><tr><td><code>tag_by_spec</code></td><td>Alle Tags über eine Spec hinweg auflisten</td></tr><tr><td><code>tag_by_collection</code></td><td>Tags innerhalb einer Collection auflisten</td></tr><tr><td><code>tag_by_id</code></td><td>Tag-Details abrufen (ID, Titel, Methodenanzahl)</td></tr><tr><td><code>endpoint_by_spec</code></td><td>Alle Endpunkte in einer Spec auflisten</td></tr><tr><td><code>endpoint_by_collection</code></td><td>Endpunkte in einer Collection auflisten</td></tr><tr><td><code>endpoint_by_tag</code></td><td>Endpunkte in einem Tag auflisten</td></tr><tr><td><code>endpoint_by_id</code></td><td>Kurze Endpunkt-Zusammenfassung (Methode, Pfad, Zusammenfassung)</td></tr><tr><td><code>search</code></td><td>Volltextsuche über alle Endpunkte</td></tr><tr><td><code>inspect</code></td><td>Vollständige OpenAPI-Operationsdetails (Parameter, Schemata)</td></tr><tr><td><code>invoke</code></td><td>Echten API-Aufruf ausführen</td></tr><tr><td><code>auth</code></td><td>Auth-Token oder Header für eine Spec abrufen</td></tr><tr><td><code>info</code></td><td>Laufzeitinformationen (Version, Specs, Konfiguration)</td></tr><tr><td><code>response_outline</code></td><td>Strukturelle Zusammenfassung einer großen Antwortdatei</td></tr><tr><td><code>response_compress</code></td><td>Große Antwort komprimieren, um sie inline einzufügen</td></tr><tr><td><code>response_slice</code></td><td>Ein Fragment einer großen Antwort extrahieren</td></tr></tbody></table><h2 id="navigationshierarchie" tabindex="-1">Navigationshierarchie <a class="header-anchor" href="#navigationshierarchie" aria-label="Permalink to &quot;Navigationshierarchie&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec_list</span></span>
<span class="line"><span>  └── spec_by_id(id)</span></span>
<span class="line"><span>        └── collection_by_spec(specId)</span></span>
<span class="line"><span>              └── collection_by_id(id)</span></span>
<span class="line"><span>                    └── tag_by_collection(collectionId)</span></span>
<span class="line"><span>                          └── tag_by_id(id)</span></span>
<span class="line"><span>                                └── endpoint_by_tag(tagId)</span></span>
<span class="line"><span>                                      └── endpoint_by_id(id)</span></span>
<span class="line"><span>                                            └── inspect(endpointId)</span></span>
<span class="line"><span>                                                  └── invoke(endpointId)</span></span></code></pre></div><p>Wenn Sie keine ID haben, verwenden Sie <code>search</code>, um Endpunkte per Abfrage zu finden. Wenn <code>invoke</code> einen <code>fileRef</code> zurückgibt (Antwort zu groß), verwenden Sie <code>response_outline</code> → <code>response_compress</code> oder <code>response_slice</code>, um die Daten zu erkunden.</p>`,18)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
